with seeded_districts as (
  insert into public.districts (name, division, slug, district_code, display_order, status) values
    ('Chattogram','Chattogram','chattogram','chattogram',45,'PUBLISHED'),('Cox''s Bazar','Chattogram','coxs-bazar','coxs-bazar',46,'PUBLISHED'),('Bandarban','Chattogram','bandarban','bandarban',47,'PUBLISHED'),('Rangamati','Chattogram','rangamati','rangamati',48,'PUBLISHED'),('Khagrachhari','Chattogram','khagrachhari','khagrachhari',49,'PUBLISHED'),('Cumilla','Chattogram','cumilla','cumilla',50,'PUBLISHED'),('Brahmanbaria','Chattogram','brahmanbaria','brahmanbaria',51,'PUBLISHED'),('Chandpur','Chattogram','chandpur','chandpur',52,'PUBLISHED'),('Feni','Chattogram','feni','feni',53,'PUBLISHED'),('Lakshmipur','Chattogram','lakshmipur','lakshmipur',54,'PUBLISHED'),('Noakhali','Chattogram','noakhali','noakhali',55,'PUBLISHED')
  on conflict (slug) do update set name=excluded.name,division=excluded.division,district_code=excluded.district_code,display_order=excluded.display_order,status=excluded.status returning id,slug,name
), source(district_slug,names) as (values
 ('chattogram','Patenga Sea Beach|Foy''s Lake|Chandranath Temple|Sitakunda Eco Park|Guliakhali Sea Beach|Banshbaria Sea Beach|Batali Hill|Chattogram War Cemetery|Ethnological Museum|DC Hill|CRB|Kattali Beach|Khoiyachora Waterfall|Napittachora Trail|Sahasradhara Waterfall'),
 ('coxs-bazar','Cox''s Bazar Sea Beach|Kolatoli Beach|Laboni Beach|Sugandha Beach|Inani Beach|Himchari National Park|Marine Drive|Ramu Buddhist temples|Maheshkhali Island|Adinath Temple|Sonadia Island|Teknaf|Naf River|St. Martin''s Island|Chera Dwip|Shah Porir Dwip|Teknaf Wildlife Sanctuary'),
 ('bandarban','Nilgiri|Nilachal|Chimbuk Hill|Boga Lake|Keokradong|Nafakhum Waterfall|Amiakhum Waterfall|Jadipai Waterfall|Shoilo Propat|Buddha Dhatu Jadi|Sangu River|Tindu|Remakri|Rijuk Waterfall|Debotakhum|Dim Pahar'),
 ('rangamati','Kaptai Lake|Hanging Bridge|Shuvolong Waterfall|Rajban Vihara|Kaptai National Park|Polwel Park|Tribal Cultural Institute|Chakma Rajbari|Sajek Valley|Konglak Hill|Ruilui Para'),
 ('khagrachhari','Alutila Cave|Risang/Richhang Waterfall|Alutila Tourist Centre|Horticulture Heritage Park|Mayung Kopal|Hatimura|Matai Pukhiri|Dighinala hills|Taiduchhara Waterfall'),
 ('cumilla','Shalban Vihara|Mainamati Museum|Mainamati War Cemetery|Rupban Mura|Itakhola Mura|Kotila Mura|Lalmai Hills|Dharmasagar|Bangladesh Academy for Rural Development area'),
 ('brahmanbaria','Kal Bhairab Temple|Titas River|Kullapathar Martyrs'' Cemetery|Akhaura historic area|Anderson Canal|Birampur/Brahmanbaria heritage sites|Kasba war-history locations'),
 ('chandpur','Chandpur Three-River Estuary|Boro Station/Mohona|Meghna River|Padma-Meghna-Dakatia confluence|Haziganj Boro Mosque|Rupsha Zamindar Bari|Chandpur riverfront'),
 ('feni','Muhuri Irrigation Project|Muhuri Lake|Rajajhir Dighi|Bijoy Singh Dighi|Shamsher Ghazi historical sites|Feni River|Sonagazi coastal area'),
 ('lakshmipur','Dalal Bazar Zamindar Bari|Tita Khan Mosque|Khowasagar Dighi|Ramgati Meghna Riverfront|Alexander Meghna embankment|Char Alexander'),
 ('noakhali','Nijhum Dwip|Nijhum Dwip National Park|Hatiya Island|Musapur Closure|Bajra Shahi Mosque|Gandhi Ashram|Birshreshtha Ruhul Amin Memorial Museum|Meghna estuary')
), listed_places as (select district_slug,trim(name) name from source cross join lateral unnest(string_to_array(names,'|')) name)
insert into public.places (district_id,name,slug,upazila_or_area,category,short_description,best_time,how_to_reach,practical_tips,status)
select d.id,p.name,trim(both '-' from regexp_replace(lower(p.name),'[^a-z0-9]+','-','g')),d.name,
case when p.name ilike '%Beach%' or p.name ilike '%Sea%' or p.name ilike '%Island%' or p.name ilike '%Dwip%' or p.name ilike '%coastal%' or p.name ilike '%estuary%' then 'Coast and nature' when p.name ilike '%Lake%' then 'Lake' when p.name ilike '%River%' or p.name ilike '%Waterfall%' or p.name ilike '%Canal%' or p.name ilike '%confluence%' then 'Riverfront and waterway' when p.name ilike '%Temple%' or p.name ilike '%Mosque%' or p.name ilike '%Vihara%' or p.name ilike '%Buddha%' then 'Religious and historic site' when p.name ilike '%Cemetery%' or p.name ilike '%Museum%' or p.name ilike '%Rajbari%' or p.name ilike '%heritage%' or p.name ilike '%Ashram%' or p.name ilike '%Mura%' then 'Historic site' when p.name ilike '%Park%' or p.name ilike '%Hill%' or p.name ilike '%Cave%' or p.name ilike '%Trail%' or p.name ilike '%Pahar%' then 'Nature and landscape' else 'Tourist place' end,
format('%s is a listed visitor destination in %s.',p.name,d.name),'November to March','Use available local transport and confirm the final approach locally.','Check current access, weather, and opening information before visiting.','PUBLISHED'
from seeded_districts d join listed_places p on p.district_slug=d.slug
on conflict (district_id,slug) do update set name=excluded.name,upazila_or_area=excluded.upazila_or_area,category=excluded.category,short_description=excluded.short_description,best_time=excluded.best_time,how_to_reach=excluded.how_to_reach,practical_tips=excluded.practical_tips,status=excluded.status;
